  "final": {
    "question": "How do you check whether a timing correction works?",
    "is_question": true,
    "form": "Calibration protocol: Objective, Reference comparison, Correction, Independent check, Result, Scope, Supporting record, Handover.",
    "object": "One protocol document consisting of eight thin matte sheets that separate, rearrange and reassemble throughout the scroll.",
    "object_in_pieces": true
  },
  "tests": {
    "swap": {
      "result": "pass",
      "reason": "The sequence rests on Iris's specific per-path decision, signed corrections, held-back check and precisely bounded numerical result."
    },
    "backdrop": {
      "result": "pass",
      "reason": "The sheet arrangements explain shared references, frozen corrections and signed residual changes, functions explicitly replaced by diagrams in the fallback."
    },
    "depth": {
      "result": "pass",
      "reason": "The reference and correction decision lead logically to independent checking, results, limitations and a closing answer."
    },
    "clipart": {
      "result": "pass",
      "reason": "The protocol sheets carry the actual approved evidence rather than serving as a stock emblem of physics."
    },
    "honesty": {
      "result": "pass",
      "reason": "The plan preserves the result's scope, personal contribution, publication statuses and supervisor-led grant attribution without inventing evidence."
    },
    "thirty_seconds": {
      "result": "pass",
      "reason": "The opening supplies Iris's identity, role, personal contribution, scoped numerical proof and immediate CV and email routes."
    },
    "plain_reader": {
      "result": "pass",
      "reason": "The opening explains comparing reported times with a reference in ordinary language while preserving the technical distinctions needed by physicists."
    }
  },
  "copied_example": false,
  "covers": {
    "phone": true,
    "reduced_motion": true,
    "no_3d": true,
    "other_needs": true,
    "look_and_type": true
  },
